UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The model selects an attacker-controlled tool that resembles an approved tool or misbinds similar parameters.","customer_symptom":"A user or operator may observe the model selects an attacker-controlled tool that resembles an approved tool or misbinds similar parameters; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in the model selects an attacker-controlled tool that resembles an approved tool or misbinds similar parameters, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["dynamic tool ecosystems"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between dynamic tool ecosystems and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the model selects an attacker-controlled tool that resembles an approved tool or misbinds similar parameters, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists.