s."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-066 approval payload, canonicalisation, tool parameter or policy-binding change","ARL-KB-066 new material transaction field or hidden execution default","ARL-KB-066 approval-substitution, parameter-mutation or binding-bypass evidence","ARL-KB-066 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='6091a0c302629b5f17efda7daaf6bcbccc8f8ee482ad81f23d3c69b440b99575', updated_at='2026-08-06' WHERE id='ARL-KB-066';
