ence.', limitations='This bounded ARL-KB-066 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='9cd58570a0ea3089505dca8b611d5f17d7bb2a1c7fe8921226c9b2a3b2b24766', updated_at='2026-08-06' WHERE entry_id='ARL-KB-066';
