UPDATE risk_knowledge_checks SET objective='Determine whether high-impact actions requiring independent approval prevent the requester or equivalent principal from approving its own transaction.', method='Using owner-authorised synthetic identities, attempt self-approval, same-principal delegation, role escalation and same-service approval for actions above the documented risk or value threshold. Verify requester and approver are independently authorized principals where separation of duties is required.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-069 assessed system, version, environment and scope for Requester can approve its own action","ARL-KB-069 control configuration or source location showing how reduce the likelihood and impact of requester can approve its own action and make the remaining risk visible.","ARL-KB-069 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-069 policy, authorization, tool or audit events proving whether the tested requester can approve its own action path executed","ARL-KB-069 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-069 passes only when “Requester can approve its own action” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tool endpoints and downstream systems and financial, administrative or state-changing actions, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-069 fails when separation of duties is absent, allowing a compromised user or agent to request and approve the same high-impact transaction, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-069 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='e3e601c66a4459d5bf81685fd0ebc237e66667aaa4789e7de13580f8bd54e0a7', updated_at='2026-08-06' WHERE entry_id='ARL-KB-069';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of requester can approve its own action and make the remaining risk visible.', recommended_remediation='Prohibit self-approval, define independent approver roles and require dual control above risk or value thresholds.', default_owner='Risk owner', priority='P0', implementation_principles_json='["ARL-KB-069: Enforce separation of duties for actions above defined risk or value thresholds.","ARL-KB-069: Prevent requester identity and derived delegated authority from satisfying the independent approver role.","ARL-KB-069: Preserve attributable request and approval identities in evidence for consequential actions."]', monitoring='For ARL-KB-069, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Risk owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-069 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-069: “Requester can approve its own action” is no longer reproducible against the exact remediated version.","ARL-KB-069: Authorised in-scope use completes successfully, remains within the documented asset scope for requester can approve its own action, and produces no unintended side effect.","ARL-KB-069: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-069: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='ebf82b82b8ec2967cadcf459f100174295b3e0668d10030659d4c6dc276ac17b', updated_at='2026-08-06' WHERE entry_id='ARL-KB-069';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='2cae6cb8184ae77e9896973c306af134cd82ebc55a1d45d4980967c24956c239', updated_at='2026-08-06' WHERE entry_id='ARL-KB-069';
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-069','critical','active','2026-10-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A token issued before user revocation, role downgrade, policy update or incident remains executable.","customer_symptom":"A user or operator may observe a token issued before user revocation, role downgrade, policy update or incident remains executable; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in a token issued before user revocation, role downgrade, policy update or incident remains executable, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","backups, runtime state and recovery infrastructure","service availability and data integrity","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents requiring human approval"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between agents requiring human approval and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a token issued before user revocation, role downgrade, policy update or incident remains executable, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-070 identity, role, policy-version, incident-state or approval-consumption change","ARL-KB-070 approval revocation or revalidation mechanism change","ARL-KB-070 stale-approval execution after user, role or policy change","ARL-KB-070 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='c86893d4ddab92660b78b753a44f784e7e86e40504b7e170a8b2d07e1083ee88', updated_at='2026-08-06' WHERE id='ARL-KB-070';
UPDATE risk_knowledge_checks SET objective='Determine whether an approval remains executable only while the approver identity, role, policy version and operational state that justified it remain valid.', method='Issue an owner-authorised synthetic approval, then before execution revoke the user, downgrade the role, change the relevant policy version or activate incident mode. Verify execution revalidates current identity, role, policy and incident state and rejects stale approval authority.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-070 assessed system, version, environment and scope for Approval remains valid after identity or policy change","ARL-KB-070 control configuration or source location showing how reduce the likelihood and impact of approval remains valid after identity or policy change and make the remaining risk visible.","ARL-KB-070 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-070 policy, authorization, tool or audit events proving whether the tested approval remains valid after identity or policy change path executed","ARL-KB-070 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-070 passes only when “Approval remains valid after identity or policy change” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-070 fails when a token issued before user revocation, role downgrade, policy update or incident remains executable, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-070 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='8c2fd4d4204175b31b8663979e0df0108b3706b3043027a499f3fc5555a7f50c', updated_at='2026-08-06' WHERE entry_id='ARL-KB-070';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of approval remains valid after identity or policy change and make the remaining risk visible.', recommended_remediation='Revalidate active identity, role, policy version and incident state at consumption; support immediate approval revocation.', default_owner='Approval service owner', priority='P0', implementation_principles_json='["ARL-KB-070: Revalidate current approver identity and role when approval is consumed.","ARL-KB-070: Bind approval validity to the relevant policy version and operational incident state.","ARL-KB-070: Support immediate revocation of outstanding approvals after identity, policy or risk-state changes."]', monitoring='For ARL-KB-070, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Approval service owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-070 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-070: “Approval remains valid after identity or policy change” is no longer reproducible against the exact remediated version.","ARL-KB-070: Authorised in-scope use completes successfully, remains within the documented asset scope for approval remains valid after identity or policy change, and produces no unintended side effect.","ARL-KB-070: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-070: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='d264bef194fa1730b070e2c03416ebff647b69ffc5a3e4333a4e29fadd9a072d', updated_at='2026-08-06' WHERE entry_id='ARL-KB-070';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='053c91dd36a5fc1c96b7b4092351cb8074968401daf1b510f0287702875aae3d', updated_at='2026-08-06' WHERE entry_id='ARL-KB-070';
